alter table private.player_permanent_consumable_effects add column if not exists art_levels jsonb not null default '{}'::jsonb check(jsonb_typeof(art_levels)='object');
alter table private.player_permanent_consumable_effects add column if not exists book_arts_imported boolean not null default false;
create or replace function private.permanent_consumable_snapshot(e private.player_permanent_consumable_effects) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('dosageBonus',e.dosage_bonus,'mindEmbodiment',e.mind_embodiment,'learnedBooks',e.learned_books,'artLevels',e.art_levels,'attributeBonuses',e.attribute_bonuses,'pillUsage',e.pill_usage,'brewUsage',e.brew_usage,'revision',e.revision)$$;
create or replace function private.book_art_id_from_item(p_item_key text) returns text language plpgsql immutable set search_path='' as $$declare parts text[];begin if p_item_key='treasureTaiyangLianshenWujuanCount' then return 'treasure-taiyang-lianshen-wujuan';elsif p_item_key='treasureChixiaoDingmingTianjianCount' then return 'treasure-chixiao-dingming-tianjian';elsif p_item_key~'^artBook_(secret|formula|sutra|escape)_[1-9]_(metal|wood|water|fire|earth)_[12]$' then parts:=string_to_array(p_item_key,'_');return 'artbook-'||parts[2]||'-t'||parts[3]||'-'||parts[4]||'-'||parts[5];end if;return null;end $$;
create or replace function private.book_art_tier(p_art_id text) returns integer language plpgsql immutable set search_path='' as $$declare m text[];begin if p_art_id in('treasure-taiyang-lianshen-wujuan','treasure-chixiao-dingming-tianjian') then return 9;end if;m:=regexp_match(p_art_id,'^artbook-(secret|formula|sutra|escape)-t([1-9])-(metal|wood|water|fire|earth)-[12]$');return case when m is null then null else m[2]::integer end;end $$;

create or replace function public.player_book_arts_bootstrap(p_channel text,p_legacy_arts jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());e private.player_permanent_consumable_effects;x jsonb;art_id text;art_level integer;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or jsonb_typeof(coalesce(p_legacy_arts,'[]'))<>'array' or jsonb_array_length(coalesce(p_legacy_arts,'[]'))>500 then raise exception '功法資料不正確';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-book-arts-'||p_channel));insert into private.player_permanent_consumable_effects(user_id,channel) values(uid,p_channel) on conflict do nothing;select * into e from private.player_permanent_consumable_effects where user_id=uid and channel=p_channel for update;if not e.book_arts_imported then for x in select value from jsonb_array_elements(coalesce(p_legacy_arts,'[]')) loop art_id:=x->>'id';art_level:=least(10,greatest(1,coalesce((x->>'level')::integer,1)));if private.book_art_tier(art_id) is not null and not e.learned_books?art_id then e.learned_books:=e.learned_books||jsonb_build_array(art_id);e.art_levels:=jsonb_set(e.art_levels,array[art_id],to_jsonb(art_level),true);end if;end loop;update private.player_permanent_consumable_effects set learned_books=e.learned_books,art_levels=e.art_levels,book_arts_imported=true,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into e;end if;return private.permanent_consumable_snapshot(e);exception when invalid_text_representation or numeric_value_out_of_range then raise exception '功法資料不正確';end $$;

create or replace function public.player_book_art_learn(p_channel text,p_item_key text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());e private.player_permanent_consumable_effects;b private.player_mail_item_balances;art_id text;begin if uid is null then raise exception '需要重新登入';end if;art_id:=private.book_art_id_from_item(p_item_key);if p_channel not in('formal','test') or art_id is null or p_request_id is null then raise exception '功法資料不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的習得請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-book-arts-'||p_channel));insert into private.player_permanent_consumable_effects(user_id,channel) values(uid,p_channel) on conflict do nothing;select * into e from private.player_permanent_consumable_effects where user_id=uid and channel=p_channel for update;if e.learned_books?art_id then raise exception '此功法已習得';end if;select * into b from private.player_mail_item_balances where user_id=uid and channel=p_channel and item_key=p_item_key for update;if b.user_id is null or b.amount<1 then raise exception '伺服器功法書數量不足';end if;update private.player_mail_item_balances set amount=amount-1,updated_at=now() where user_id=uid and channel=p_channel and item_key=p_item_key returning * into b;update private.player_permanent_consumable_effects set learned_books=learned_books||jsonb_build_array(art_id),art_levels=jsonb_set(art_levels,array[art_id],'1'::jsonb,true),revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into e;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,e.revision,'book_art_learned',p_request_id,jsonb_build_object('artId',art_id,'itemKey',p_item_key));return jsonb_build_object('effects',private.permanent_consumable_snapshot(e),'itemBalances',jsonb_build_object(p_item_key,b.amount));end $$;

create or replace function public.player_book_art_upgrade(p_channel text,p_art_id text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());e private.player_permanent_consumable_effects;w private.player_resource_wallets;tier integer;art_level integer;cost bigint;begin if uid is null then raise exception '需要重新登入';end if;tier:=private.book_art_tier(p_art_id);if p_channel not in('formal','test') or tier is null or p_request_id is null then raise exception '功法資料不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的升級請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-book-arts-'||p_channel));select * into e from private.player_permanent_consumable_effects where user_id=uid and channel=p_channel for update;if e.user_id is null or not e.learned_books?p_art_id then raise exception '尚未習得此功法';end if;art_level:=coalesce((e.art_levels->>p_art_id)::integer,1);if art_level>=10 then raise exception '功法已達滿級';end if;cost:=round(500*tier*tier*power(1.5,art_level-1));select * into w from private.player_resource_wallets where user_id=uid and channel=p_channel for update;if w.user_id is null or w.aura<cost then raise exception '靈氣不足';end if;update private.player_resource_wallets set aura=aura-cost,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into w;update private.player_permanent_consumable_effects set art_levels=jsonb_set(art_levels,array[p_art_id],to_jsonb(art_level+1),true),revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into e;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,e.revision,'book_art_upgraded',p_request_id,jsonb_build_object('artId',p_art_id,'level',art_level+1,'cost',cost));return jsonb_build_object('effects',private.permanent_consumable_snapshot(e),'wallet',private.wallet_snapshot(w),'cost',cost);end $$;

revoke all on function private.book_art_id_from_item(text),private.book_art_tier(text) from public,anon,authenticated;
revoke execute on function public.player_book_arts_bootstrap(text,jsonb),public.player_book_art_learn(text,text,uuid),public.player_book_art_upgrade(text,text,uuid) from public,anon;
grant execute on function public.player_book_arts_bootstrap(text,jsonb),public.player_book_art_learn(text,text,uuid),public.player_book_art_upgrade(text,text,uuid) to authenticated;
